import{z as i,x as l,o as t,c as s,q as r,j as n,D as E,d as A,s as e,S as o,b as m}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"Mack / Notch 溶解模型","description":"","frontmatter":{"title":"Mack / Notch 溶解模型","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/dissolution-mack.md","filePath":"litho/dissolution-mack.md","lastUpdated":1791063341000}'),h={name:"litho/dissolution-mack.md"};function p(c,a,R,d,_,C){const B=l("Mermaid");return t(),s("div",null,[a[2]||(a[2]=r('<h1 id="mack-notch-溶解模型" tabindex="-1">Mack / Notch 溶解模型 <a class="header-anchor" href="#mack-notch-溶解模型" aria-label="Permalink to &quot;Mack / Notch 溶解模型&quot;">​</a></h1><div class="epigraph"><p>衬度曲线是均匀垫上的剩余厚度；剖面要从溶解速率 $R$ 对抑制剂分数的函数沿厚度积分而来。Mack 给出紧凑的 $R(m)$。</p><footer>—— 据 Mack 对显影速率模型（原 Mack 式与 Notch）的定义整理</footer></div><p><a href="/litho/resist-contrast-curve">上一课</a>钉死了 \\(T(\\log E)\\) 与 \\(\\gamma\\)，并点名「Mack 显影模型是产线紧凑形式之一」。缺口是：还没有把那条曲线背后的速率函数写出来——阈值模型只是 \\(R\\) 在目标厚度处的工作点。本课钉 Mack / Notch。沿 \\(z\\) 的驻波让 \\(R\\) 不再均匀，留给<a href="/litho/standing-wave-barc">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(\\gamma\\) 来自大面积均匀曝光。密线的边是三维的：溶解前沿从表面往下、从侧面往里走，停在「速率 × 时间刚好不够」的等值面上。只有 \\(\\gamma\\) 没有 \\(R(m)\\)，OPC 抗蚀剂模块只能用一条强度阈值，剖面角、残胶、清底时间都进不去。缺口因此是 \\(R\\) 对剩余抑制剂（或保护基）分数 \\(m\\) 的函数。</p><p><span class="marginnote">术语翻译：溶解选择度 \\(n\\) 就是「亮区比暗区化得快多少倍」的陡度旋钮——\\(n\\) 越大，\\(R(m)\\) 越像理想开关：亮区瞬间洞穿、暗区纹丝不动。这把「锋利」是有账单的：它同时放大剂量噪声，后面机制段会回到这句话。</span></p><p>DNQ 体系里 \\(m\\) 是 PAC 分数；CAR 里 \\(m\\) 是仍被保护的比例。上一课不重推 CAR 循环，本课只要求：\\(m\\) 从 1（未转）到 0（转完），\\(R\\) 从 \\(R_\\mathrm{min}\\) 升到 \\(R_\\mathrm{max}\\)。</p><h3 id="阈值是-的切片" tabindex="-1">阈值是 \\(R(m)\\) 的切片 <a class="header-anchor" href="#阈值是-的切片" aria-label="Permalink to &quot;阈值是 $R(m)$ 的切片&quot;">​</a></h3><p>固定显影时间，把 \\(R(m(E))\\) 沿厚度积到穿或积不满，就得到 \\(T(E)\\)，从而有 \\(\\gamma\\)。极陡的 \\(R(m)\\) 给出大 \\(\\gamma\\)；Notch 形状（先几乎不溶，过阈值后猛升）是 CAR 常见拟合，不是另一种光学对比度。</p><p><span class="marginnote">\\(R_\\mathrm{min}\\) 不是零：暗侵蚀在未曝光区也掉厚。长时间显影会吃掉暗区，CD 漂移。模型必须保留 \\(R_\\mathrm{min}\\)，不能写成理想开关。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>原 Mack 显影模型用四个材料参数：\\(R_\\mathrm{max}\\)、\\(R_\\mathrm{min}\\)、溶解选择度 \\(n\\)、阈值抑制剂分数 \\(m_\\mathrm{th}\\)。常用紧凑式</p> \\[R(m)=R_\\mathrm{max}\\frac{(a+1)(1-m)^n}{a+(1-m)^n}+R_\\mathrm{min}, \\]<p>其中 \\(a=\\dfrac{n+1}{n-1}(1-m_\\mathrm{th})^n\\)，使 \\(R(m)\\) 在阈值附近获得需要的陡度。这就是口语里的「Mack 四参数」。PROLITH 一类模拟器、以及 OPC 的紧凑胶模块，用的就是这一族，而不是分子动力学。\\(n\\to\\infty\\) 时趋向理想开关，对应上一课极大的 \\(\\gamma\\)，也对应本课已经警告过的噪声放大。</p><p><span class="marginnote">数字实例：取 \\(R_\\mathrm{max}=100\\,\\mathrm{nm/s}\\)、\\(R_\\mathrm{min}=1\\,\\mathrm{nm/s}\\)，选择比一百倍。清 \\(1\\,\\mu\\mathrm{m}\\) 厚的亮区只需约 10 秒，但显影 60 秒时暗区也掉了 \\(60\\,\\mathrm{nm}\\)——约一成膜厚。看起来「不溶」的材料，时间够长照样掉厚，这就是 \\(R_\\mathrm{min}\\) 绝不能当零的原因。</span></p><p>Notch 变体在 \\(R(m)\\) 上再乘（或再叠加）一个更陡的阈值因子：低脱保护时速率几乎贴着 \\(R_\\mathrm{min}\\)，过「槽口」后迅速靠近 \\(R_\\mathrm{max}\\)。CAR 的实验溶速常长这样——保护基掉到某一分数之前聚合物仍疏水。拟合 Notch 是为了把这张形状送进计算光刻，不是新发明一种显影液。</p>',16)),(t(),n(o,null,{default:E(()=>[e(B,{id:"mermaid-44",class:"mermaid",graph:"flowchart%20TD%0A%20%20M%5B%22%E6%8A%91%E5%88%B6%E5%89%82%E5%88%86%E6%95%B0%20m%22%5D%20--%3E%20R%5B%22R(m)%20Mack%20%2F%20Notch%22%5D%0A%20%20R%20--%3E%20INT%5B%22%E6%B2%BF%E5%8E%9A%E5%BA%A6%E7%A7%AF%E5%88%86%E6%98%BE%E5%BD%B1%E6%97%B6%E9%97%B4%22%5D%0A%20%20INT%20--%3E%20PROF%5B%22%E4%B8%89%E7%BB%B4%E6%B5%AE%E9%9B%95%22%5D%0A%20%20PROF%20--%3E%20GAMMA%5B%22%E4%B8%8A%E4%B8%80%E8%AF%BE%EF%BC%9A%CE%B3%20%2F%20T(log%20E)%22%5D%0A%20%20PROF%20--%3E%20SW%5B%22%E4%B8%8B%E4%B8%80%E8%AF%BE%EF%BC%9A%E9%A9%BB%E6%B3%A2%E6%94%B9%20I(z)%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=m("h2",{id:"机制",tabindex:"-1"},[A("机制 "),m("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=m("p",null,"溶解前沿的法向速度就是当地 \\(R\\)。亮区 \\(m\\) 低，\\(R\\) 大，先被挖穿；边沿 \\(m\\) 处于阈值附近，前沿走得慢，侧壁形状由 \\(R(m)\\) 的陡度与空中像沿 \\(x\\) 的斜率共同决定。\\(n\\) 大、Notch 深，侧壁更直，同时对剂量噪声更敏感——与上一课「γ 过大放大 LWR」是同一句话的速率版。清底时间由底部 \\(R\\) 与胶厚决定：底部 \\(m\\) 若因吸收或驻波而偏高，即使表面已经切锐，仍会留残胶。这是阈值模型看不见、速率积分看得见的差。",-1)),a[5]||(a[5]=m("p",null,"沿 \\(z\\)，若 \\(I\\) 均匀，积分只是时间够不够清底。下一课会取消这个若：驻波让 \\(m(z)\\) 振荡，\\(R\\) 跟着振荡，侧壁出现波纹。本课的 \\(R(m)\\) 仍然成立，输入 \\(m\\) 不再是常数。",-1)),a[6]||(a[6]=m("p",null,[m("span",{class:"marginnote"},"负显影把「谁溶」翻转，\\(R(m)\\) 的自变量改成另一套极性，函数形状要重拟合。不要把正胶 Mack 参数抄到 NTD 上。")],-1)),(t(),n(o,null,{default:E(()=>[e(B,{id:"mermaid-57",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN%5B%22%E5%90%8C%E4%B8%80%E5%BC%A0%E7%A9%BA%E4%B8%AD%E5%83%8F%E4%B8%8E%20m(x%2Cz)%22%5D%20--%3E%20TH%5B%22%E9%98%88%E5%80%BC%E6%A8%A1%E5%9E%8B%3A%20%E4%B8%80%E6%9D%A1%E5%BC%BA%E5%BA%A6%E7%AD%89%E5%80%BC%E7%BA%BF%22%5D%0A%20%20IN%20--%3E%20RM%5B%22%E9%80%9F%E7%8E%87%E6%A8%A1%E5%9E%8B%3A%20R(m)%20%E6%B2%BF%E7%A9%BA%E9%97%B4%E7%A7%AF%E5%88%86%22%5D%0A%20%20TH%20--%3E%20A1%5B%22%E5%9B%9E%E7%AD%94%3A%20%E7%BA%BF%E5%9C%A8%E5%93%AA%E9%87%8C%2C%20%CE%B3%20%E5%A4%9A%E5%A4%A7%22%5D%0A%20%20TH%20--%3E%20A2%5B%22%E7%9C%8B%E4%B8%8D%E8%A7%81%3A%20%E5%89%96%E9%9D%A2%E8%A7%92%2C%20%E6%AE%8B%E8%83%B6%2C%20%E6%B8%85%E5%BA%95%E6%97%B6%E9%97%B4%22%5D%0A%20%20RM%20--%3E%20B1%5B%22%E5%9B%9E%E7%AD%94%3A%20%E4%BE%A7%E5%A3%81%E8%A7%92%E4%B8%8E%E6%B8%85%E5%BA%95%E6%97%B6%E9%97%B4%22%5D%0A%20%20RM%20--%3E%20B2%5B%22%E4%BB%A3%E4%BB%B7%3A%20%E8%A6%81%E5%9B%9B%E4%B8%AA%E5%8F%82%E6%95%B0%E5%B9%B6%E5%81%9A%E7%A7%AF%E5%88%86%22%5D%0A%20%20A1%20--%3E%20U1%5B%22%E7%94%A8%E9%80%94%3A%20OPC%20%E5%BF%AB%E7%AD%9B%22%5D%0A%20%20B1%20--%3E%20U2%5B%22%E7%94%A8%E9%80%94%3A%20%E5%B7%A5%E8%89%BA%E7%AA%97%E5%8F%A3%E4%B8%8E%E5%89%96%E9%9D%A2%E6%8A%8A%E5%85%B3%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[A(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=r('<p><span class="marginnote">直觉类比：\\(R(m)\\) 像一个极陡的音量旋钮——转过头一点点，音量从静音跳到最大。刻线享受这种「干脆」：侧壁笔直；但剂量只要抖一点，响的变静、静的变响，线宽粗糙度跟着放大。陡峭既是卖点，也是风险。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲喷雾、搅拌、显影液耗尽的流体力学。那些会改有效时间，不改 \\(R(m)\\) 作为材料紧凑描述的地位。也不把某胶拟合出的 \\(n=20\\) 写进所有层：PEB、显影液浓度、温度都改参数。空中像对比 \\(C\\) 禁止再与 \\(n\\) 混名。</p><p>驻波与 BARC 是下一课：本课默认 \\(I(z)\\) 已被说成「指定的」，以便先把速率函数钉住。侧壁角作为刻蚀输入，再下一课才从剖面几何来讲。</p><p>参数随 PEB、显影液浓度和温度变。换胶或换显影液等于作废 \\(n\\) 与 \\(m_\\mathrm{th}\\)。不要把某一层拟合表抄到全厂。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>剖面由 \\(R(m)\\) 沿空间积分得到；\\(\\gamma\\) 是均匀垫上的后果。</li><li>Mack 四参数给出从 \\(R_\\mathrm{min}\\) 到 \\(R_\\mathrm{max}\\) 的陡开关；Notch 拟合 CAR 的延迟起溶。</li><li>OPC 阈值模型是 \\(R(m)\\) 的工作点切片。</li><li>下一课取消 \\(I(z)\\) 均匀的假设。</li><li>出处：Mack, <em>Fundamental Principles of Optical Lithography</em>（Mack / Notch 显影速率）。</li></ul>',7))])}const D=i(h,[["render",p]]);export{u as __pageData,D as default};
